///
/// Returns [`Error::Api`] for a non-success status (its body truncated at
/// `cap`, never `ResponseTooLarge`), [`Error::Serde`] when the success body
/// does not match `T`, [`Error::ResponseTooLarge`] when a success body exceeds
/// `cap`, or [`Error::Transport`] when a success body stream fails mid-read.
pub async fn decode_json<T: DeserializeOwned>(response: http::Response<SdkBody>, cap: usize) -> Result<T, Error> {
    let (parts, body) = response.into_parts();
    let request_id = request_id(&parts.headers);
    // Status first: only success bodies may fail collection. Collecting before
    // checking would let an oversized error page (a 502 serving HTML) surface
    // as ResponseTooLarge, destroying the status/headers/request id.
    if parts.status.is_success() {
        // Decode failures on the success path are the ones worth tracing: a
        // non-success status is already reported as the terminal outcome by
        // `send_with_retries` and surfaces to the caller as a typed `ApiError`.
        let bytes = collect_capped(body, cap)
            .await
            .inspect_err(|error| trace::decode_failed(parts.status, error))?;
        // A successful response with an empty body (a 204, or a 200/202 with no
        // content) is not valid JSON; decode it as `null` so `Option<T>` and
        // unit-like return types succeed instead of failing with an EOF error.
        if bytes.is_empty() {
            return serde_json::from_slice(b"null")
                .map_err(Error::from)
                .inspect_err(|error| trace::decode_failed(parts.status, error));
        }
        serde_json::from_slice(&bytes)
            .map_err(Error::from)
            .inspect_err(|error| trace::decode_failed(parts.status, error))
    } else {
        let (bytes, truncated) = collect_truncated(body, cap).await;
        Err(Error::from(ApiError::from_parts(
            parts.status.as_u16(),
            parts.headers,
            request_id,
            &bytes,
            truncated,
        )))
    }
}

